"""Path rules for archive members. A member's name is a POSIX path relative to the archive's root."""
import os

from .errors import UnsafeArchive

MAX_NAME = 1024
MAX_LINKS = 40  # links one path may pass through before it counts as a loop


def clean_name(name):
    """The member name as a relative path with no empty or "." parts. UnsafeArchive for an absolute name, a drive
    letter, a ".." part, a backslash or a NUL."""
    if not isinstance(name, str) or not name or "\x00" in name or "\\" in name:
        raise UnsafeArchive(f"bad member name {name!r}")
    if name.startswith("/") or (len(name) > 1 and name[1] == ":"):
        raise UnsafeArchive(f"{name} is an absolute path")
    parts = [part for part in name.split("/") if part not in ("", ".")]
    if not parts:
        raise UnsafeArchive(f"bad member name {name!r}")
    if ".." in parts:
        raise UnsafeArchive(f"{name} climbs out with ..")
    clean = "/".join(parts)
    if len(clean) > MAX_NAME:
        raise UnsafeArchive(f"a member name is longer than {MAX_NAME} characters")
    return clean


def check_target(name, linkname):
    """UnsafeArchive unless linkname is a relative path of the kind a link in an archive may hold: not empty, no
    backslash, not absolute and no drive letter."""
    if not isinstance(linkname, str) or not linkname or "\\" in linkname:
        raise UnsafeArchive(f"{name} links to {linkname!r}, which isn't a relative path")
    if linkname.startswith("/") or (len(linkname) > 1 and linkname[1] == ":"):
        raise UnsafeArchive(f"{name} links to {linkname}, an absolute path")


def resolve(tree, parts, start=(), strict=False):
    """Where the path parts leads from the folder start, as a tuple of names with every link on the way followed.

    tree maps each path the archive has made so far, as a tuple of names, to ("dir", None), ("file", None) or
    ("link", target). A link's target is read from the folder the link is in, the way the kernel reads it, so ".."
    after a link climbs from the link's target. A path that climbs above the destination, or a chain of links longer
    than MAX_LINKS, raises UnsafeArchive. A name the tree doesn't hold is taken to be a folder yet to be made.

    strict is for writes: a write may go through a link only to a folder that is already there, and nothing may
    walk on past a file, so a path the kernel would fail on raises UnsafeArchive rather than being read lexically."""
    cur, hops = tuple(start), 0
    todo = [(part, False) for part in parts]  # (name, whether it came from a link's target)
    while todo:
        part, from_link = todo.pop(0)
        if part in ("", "."):
            continue
        if part == "..":
            if not cur:
                raise UnsafeArchive("a path climbs out of the destination")
            cur = cur[:-1]
            continue
        here = cur + (part,)
        kind, target = tree.get(here, (None, None))
        if kind == "link":
            hops += 1
            if hops > MAX_LINKS:
                raise UnsafeArchive("a chain of links loops")
            todo[:0] = [(p, True) for p in target.split("/")]
            continue
        if strict:
            if kind is None and from_link:
                raise UnsafeArchive(f"a link leads to {'/'.join(here)}, which isn't there yet")
            if kind == "file" and todo:
                raise UnsafeArchive(f"{'/'.join(here)} is a file, not a folder")
        cur = here
    return cur


def make_folders(tree, folder, name):
    """Record each folder on the way to folder, a path resolve returned, as a folder unless it is one already.
    UnsafeArchive when one of them is a file, because name can't be written through a file."""
    for depth in range(1, len(folder) + 1):
        here = folder[:depth]
        kind = tree.get(here, (None, None))[0]
        if kind is None:
            tree[here] = ("dir", None)
        elif kind != "dir":
            raise UnsafeArchive(f"{name} would be written through {'/'.join(here)}, which isn't a folder")


def under(root, parts):
    """The absolute path of the names parts under root."""
    return os.path.join(root, *parts)

