"""MANIFEST.json, written at the root of every backup: the sha256 of each file and the target of each link."""
import hashlib
import json
import os

from archive import paths
from archive.errors import UnsafeArchive
from archive.pack import walk

NAME = "MANIFEST.json"


class ManifestMismatch(ValueError):
    pass


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def build(root):
    """{"files": {path: sha256}, "links": {path: target}} for the tree under root, paths relative and POSIX."""
    files, links = {}, {}
    for rel, path in walk(root):
        if rel == NAME:
            continue
        if os.path.islink(path):
            links[rel] = os.readlink(path)
        elif os.path.isfile(path):
            files[rel] = sha256(path)
    return {"files": files, "links": links}


def dumps(manifest):
    return json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def verify(root, manifest):
    """ManifestMismatch unless every file and link the manifest lists is under root as it says. The manifest comes
    from the backup, so a path that leaves root is refused rather than read."""
    for rel, digest in manifest.get("files", {}).items():
        path = _under(root, rel)
        if os.path.islink(path) or not os.path.isfile(path):
            raise ManifestMismatch(f"{rel} is missing")
        if sha256(path) != digest:
            raise ManifestMismatch(f"{rel} doesn't match its checksum")
    for rel, target in manifest.get("links", {}).items():
        path = _under(root, rel)
        if not os.path.islink(path) or os.readlink(path) != target:
            raise ManifestMismatch(f"{rel} should link to {target}")


def _under(root, rel):
    try:
        return os.path.join(root, *paths.clean_name(rel).split("/"))
    except UnsafeArchive as e:
        raise ManifestMismatch(f"{rel!r} in the backup's {NAME} isn't a path inside it: {e}") from None

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.

Checking each name and link target on its own isn't enough: a link extracted earlier changes where later names
and link targets lead (`x/l -> ..` then `e -> x/l/..` points above the destination, and `e/f` is then written
there). So the check replays the whole archive against a model of the destination - what is already on disk
plus what the archive has created so far - and follows links the way the kernel will.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_HOPS = 40  # Linux's limit on links followed while resolving one path

DIR, FILE, LINK = "dir", "file", "link"


class _Escape(Exception):
    pass


class _Loop(Exception):
    pass


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan, created = plan_members(root, members)
        try:
            for member, target in plan:
                write_member(tar, member, target)
        except BaseException:
            _undo(created)
            raise
    return [paths.clean_name(m.name) for m in members]


class _Tree:
    """The destination as it will be: what's on disk under root, plus what the archive has created so far."""

    def __init__(self, root):
        self.root = root
        self.made = {}
        self.created = []  # paths this extraction creates, in the order it creates them

    def kind(self, path):
        """(DIR,), (FILE,), (LINK, target) or None, for an absolute path with no links in it, under root."""
        if path in self.made:
            return self.made[path]
        try:
            st = os.lstat(path)
        except (FileNotFoundError, NotADirectoryError):
            return None
        if stat.S_ISLNK(st.st_mode):
            return (LINK, os.readlink(path))
        if stat.S_ISDIR(st.st_mode):
            return (DIR,)
        return (FILE,)

    def add(self, path, kind):
        self.made[path] = kind
        self.created.append(path)

    def resolve(self, base, rel):
        """Where the relative path rel leads from the folder base, following every link the way the kernel would.
        Returns an absolute path with no links in it. _Escape if it ever leaves root or meets an absolute link,
        _Loop after MAX_HOPS links. Parts that don't exist yet are taken as written."""
        cur = base
        stack = list(reversed(rel.split("/")))
        hops = 0
        while stack:
            part = stack.pop()
            if part in ("", "."):
                continue
            if part == "..":
                if cur == self.root:
                    raise _Escape()
                cur = os.path.dirname(cur)
                continue
            nxt = os.path.join(cur, part)
            found = self.kind(nxt)
            if found is not None and found[0] == LINK:
                hops += 1
                if hops > MAX_HOPS:
                    raise _Loop()
                if not found[1] or found[1].startswith("/"):
                    raise _Escape()
                stack.extend(reversed(found[1].split("/")))
                continue
            cur = nxt
        return cur


def plan_members(root, members):
    """([(member, the absolute path it goes to), ...], [paths it creates]) once every member has passed, or
    UnsafeArchive. The paths have no links in them, so writing to them can't be redirected."""
    tree = _Tree(root)
    seen = set()
    plan = []
    links = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.issym():
            if not member.linkname or os.path.isabs(member.linkname) or member.linkname.startswith("/"):
                raise UnsafeArchive(f"{name} links to an absolute path")
            if "\x00" in member.linkname:
                raise UnsafeArchive(f"{name} has a bad link target")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")

        parent_name, _, base = name.rpartition("/")
        try:
            parent = tree.resolve(root, parent_name)
        except _Escape:
            raise UnsafeArchive(f"{name} would be written outside the destination") from None
        except _Loop:
            raise UnsafeArchive(f"{name} would be written through a loop of links") from None
        if not paths.is_within(root, parent):
            raise UnsafeArchive(f"{name} would be written outside the destination")
        # Every folder from root down to parent must be a folder, or not exist yet (then it is made).
        rel = os.path.relpath(parent, root)
        cur = root
        for part in ([] if rel == "." else rel.split(os.sep)):
            cur = os.path.join(cur, part)
            found = tree.kind(cur)
            if found is None:
                tree.add(cur, (DIR,))
            elif found[0] != DIR:
                raise UnsafeArchive(f"{name} would be written inside something that isn't a folder")
        target = os.path.join(parent, base)
        found = tree.kind(target)
        if member.isdir():
            if found is None:
                tree.add(target, (DIR,))
            elif found[0] != DIR:
                raise UnsafeArchive(f"{name} is a folder, but something else is already there")
        else:
            if found is not None:
                raise UnsafeArchive(f"{name} would replace something already there")
            if member.issym():
                tree.add(target, (LINK, member.linkname))
                links.append((name, member.linkname, parent))
            else:
                tree.add(target, (FILE,))
        plan.append((member, target))

    # Links are checked against the destination as the whole archive leaves it, so a link to a file later in the
    # archive is fine, and a link that a later link would redirect outside is not.
    for name, linkname, parent in links:
        try:
            tree.resolve(parent, linkname)
        except _Escape:
            raise UnsafeArchive(f"{name} links to {linkname}, outside the destination") from None
        except _Loop:
            pass  # a loop of links leads nowhere, so it can't lead out
    return plan, tree.created


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    with tar.extractfile(member) as src, os.fdopen(fd, "wb") as out:
        shutil.copyfileobj(src, out)
        os.fchmod(out.fileno(), EXEC_MODE if member.mode & 0o100 else FILE_MODE)


def _undo(created):
    """Remove what a failed extraction made, newest first, so the destination is as it was."""
    for path in reversed(created):
        try:
            if os.path.islink(path) or not os.path.isdir(path):
                os.unlink(path)
            else:
                os.rmdir(path)
        except OSError:
            pass

