"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export is read one line at a time. Each line becomes a candidate record, which is sorted into runs spilled to a
scratch directory beside dst; the runs are then merged to keep each entry's current revision, and merged again into
the file order. Memory use is bounded by RUN_RECORDS, not by the size of the export. dst is only replaced once every
line has been migrated, so a MigrationError leaves it untouched.
"""
import heapq
import json
import os
import pickle
import shutil
import tempfile
from operator import itemgetter

from . import accounts as accounts_file
from . import kinds, money, timefmt, v2, v3
from .errors import MigrationError

RUN_RECORDS = 200_000  # records held in memory before a sorted run is spilled to disk
MERGE_WIDTH = 64       # runs merged at once, which bounds how many files are open together

_BY_ID = itemgetter(0, 1, 2)  # (id, rev, line number)


def migrate(src, accounts, dst):
    held = accounts_file.load(accounts)
    scratch = tempfile.mkdtemp(prefix=".migrate-", dir=os.path.dirname(os.path.abspath(dst)))
    try:
        candidates = (_candidate(raw, number, held) for number, raw in _lines(src))
        by_id = _reduce(_sorted_runs(candidates, _BY_ID, scratch), _BY_ID, scratch)
        by_order = _reduce(_sorted_runs(_current(_merged(by_id, _BY_ID)), v3.order_key, scratch),
                           v3.order_key, scratch)
        out = os.path.join(scratch, "ledger_v3.jsonl")
        count = 0
        with open(out, "w", encoding="utf-8", newline="\n") as f:
            for record in _merged(by_order, v3.order_key):
                f.write(v3.dump_line(record))
                count += 1
        os.replace(out, dst)
        return count
    finally:
        shutil.rmtree(scratch, ignore_errors=True)


def _lines(src):
    """(line number, raw bytes) for each non-blank line of the export."""
    with open(src, "rb") as f:
        for number, raw in enumerate(f, 1):
            if raw.strip():
                yield number, raw


def _candidate(raw, number, held):
    """(id, rev, line number, v3 record) for one v2 line; MigrationError if the line can't be migrated."""
    try:
        record = _convert(raw, held)
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    return record["id"], record["source_rev"], number, record


def _convert(raw, held):
    """The v3 record for one v2 line. ValueError, saying why, when the line can't be migrated."""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise ValueError("not UTF-8") from None
    try:
        line = json.loads(text)
    except ValueError as e:
        raise ValueError(f"not JSON ({e})") from None
    v2.check(line, None)
    account = held.get(line["account"])
    if account is None:
        raise ValueError(f"account {line['account']!r} isn't in the accounts file")
    kind = kinds.LEGACY.get(line["kind"], line["kind"])
    if kind not in kinds.TYPES:
        raise ValueError(f"unknown kind {line['kind']!r}")
    currency = account.currency if line["currency"] is None else line["currency"]
    if not money.is_currency(currency):
        raise ValueError(f"bad currency {currency!r}")
    minor = money.to_minor(line["amount"], currency)
    if minor <= 0:
        raise ValueError(f"amount {line['amount']} isn't positive")
    stamp = timefmt.parse_ts(line["ts"])
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=account.tz)
    record = {"id": line["id"], "account": line["account"], "type": kind,
              "amount_minor": minor * kinds.SIGN[kind], "currency": currency,
              "posted_at": timefmt.to_utc_z(stamp), "memo": line["memo"], "source_rev": line["rev"]}
    v3.validate(record)
    return record


def _current(candidates):
    """The current revision of each id. Candidates arrive sorted by id, rev and line, so it is the last of each id."""
    last = None
    for item in candidates:
        if last is not None and item[0] != last[0]:
            yield last[3]
        last = item
    if last is not None:
        yield last[3]


def _new_run(scratch):
    fd, path = tempfile.mkstemp(dir=scratch, suffix=".run")
    os.close(fd)
    return path


def _sorted_runs(items, key, scratch):
    """Sort items into run files of RUN_RECORDS each; returns their paths."""
    paths, batch = [], []
    for item in items:
        batch.append(item)
        if len(batch) == RUN_RECORDS:
            paths.append(_spill(batch, key, scratch))
            batch = []
    if batch:
        paths.append(_spill(batch, key, scratch))
    return paths


def _spill(batch, key, scratch):
    batch.sort(key=key)
    path = _new_run(scratch)
    with open(path, "wb") as f:
        for item in batch:
            pickle.dump(item, f, pickle.HIGHEST_PROTOCOL)
    return path


def _read_run(path):
    with open(path, "rb") as f:
        while True:
            try:
                yield pickle.load(f)
            except EOFError:
                return


def _merged(paths, key):
    """Every item of the run files, in key order."""
    return heapq.merge(*(_read_run(p) for p in paths), key=key)


def _reduce(paths, key, scratch):
    """Merge runs MERGE_WIDTH at a time until no more than MERGE_WIDTH remain."""
    while len(paths) > MERGE_WIDTH:
        merged = []
        for start in range(0, len(paths), MERGE_WIDTH):
            group = paths[start:start + MERGE_WIDTH]
            path = _new_run(scratch)
            with open(path, "wb") as f:
                for item in _merged(group, key):
                    pickle.dump(item, f, pickle.HIGHEST_PROTOCOL)
            for old in group:
                os.remove(old)
            merged.append(path)
        paths = merged
    return paths

