from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    # Three statements in total, grouped in Python. Rows are fetched in id order and
    # grouped in that order, so each balance is accumulated in the same sequence as the
    # original per-account / per-invoice queries (invoice, then its payments, ...).
    invoices_by_account = {}
    for invoice_id, account_id, cents in conn.execute(
            "SELECT id, account_id, amount_cents FROM invoices WHERE voided = 0 ORDER BY id").fetchall():
        invoices_by_account.setdefault(account_id, []).append((invoice_id, cents))

    payments_by_invoice = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method"
            " FROM payments p JOIN invoices i ON i.id = p.invoice_id"
            " WHERE i.voided = 0 ORDER BY p.id").fetchall():
        payments_by_invoice.setdefault(invoice_id, []).append((paid, status, method))

    result = {}
    for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall():
        owed = 0
        for invoice_id, cents in invoices_by_account.get(account_id, ()):
            owed += cents
            for paid, status, method in payments_by_invoice.get(invoice_id, ()):
