from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    # Three statements in all, however many accounts, invoices or payments there are. Rows are read
    # in id order and the arithmetic runs per account in accounts order, invoice by invoice, payment by
    # payment, as the old per-account queries did. So sums (even for non-integer values) and the first
    # error raised for bad data come out identical.
    result = {account_id: 0 for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall()}
    invoices_of = {account_id: [] for account_id in result}
    for invoice_id, account_id, cents in conn.execute(
            "SELECT id, account_id, amount_cents FROM invoices WHERE voided = 0 ORDER BY id").fetchall():
        if account_id in invoices_of:
            invoices_of[account_id].append((invoice_id, cents))
    live = {invoice_id for invoices in invoices_of.values() for invoice_id, _ in invoices}
    counted = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT invoice_id, amount_cents, status, method FROM payments ORDER BY id").fetchall():
        if invoice_id in live and rules.counts(status, method):
            counted.setdefault(invoice_id, []).append(paid)
    for account_id, invoices in invoices_of.items():
        for invoice_id, cents in invoices:
            result[account_id] += cents
            for paid in counted.get(invoice_id, ()):
                result[account_id] -= paid
    return result

