import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyReused(Exception):
    """The idempotency key was already used for a request with a different body."""


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already recorded under that key is
    returned as-is (no new charge) if it has the same customer and amount;
    otherwise KeyReused is raised. The lookup, charge and insert run in one
    write transaction so concurrent requests with the same key can't both charge.
    """
    if idempotency_key is None:
        return _charge_and_record(conn, customer_id, cents, None)

    # Take the database write lock before the lookup (sqlite3 would otherwise
    # only BEGIN at the first INSERT, after the lookup), so a second request with
    # the same key waits here until the first one has committed its payment.
    conn.execute("BEGIN IMMEDIATE")
    try:
        existing = _find_by_key(conn, idempotency_key)
        if existing is None:
            try:
                return _charge_and_record(conn, customer_id, cents, idempotency_key)
            except sqlite3.IntegrityError:
                # Another request recorded this key first; answer as if we had
                # found it in the lookup. Rolling back also drops our charge row.
                conn.rollback()
                existing = _find_by_key(conn, idempotency_key)
                if existing is None:
                    raise
        conn.rollback()  # read-only from here on; release the write lock
        return _replay(existing, customer_id, cents)
    except BaseException:
        if conn.in_transaction:
            conn.rollback()
        raise


def _charge_and_record(conn, customer_id, cents, idempotency_key):
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute(
        "INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
        (customer_id, cents, charge_id, idempotency_key))
    conn.commit()
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}


def _find_by_key(conn, idempotency_key):
    return conn.execute(
        "SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
        (idempotency_key,)).fetchone()


def _replay(row, customer_id, cents):
    if (row["customer_id"], row["cents"]) != (customer_id, cents):
        raise KeyReused()
    return {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"],
            "charge_id": row["charge_id"]}

