import time

from payments import gateway, idempotency, service

KEY_HEADER = "idempotency-key"  # header names are case-insensitive
MAX_KEY_LENGTH = 255


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    An optional Idempotency-Key header makes a retry safe: the first response for
    a key is stored and replayed for later requests with the same key and body."""
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _header(request, KEY_HEADER)
    if key is None:
        return _create(conn, customer_id, cents)
    if not isinstance(key, str) or not 0 < len(key) <= MAX_KEY_LENGTH:
        return 400, {"error": f"Idempotency-Key must be 1 to {MAX_KEY_LENGTH} characters"}
    return _create_once(conn, key, customer_id, cents)


def _header(request, name):
    for header, value in (request.get("headers") or {}).items():
        if header.lower() == name:
            return value
    return None


def _create(conn, customer_id, cents):
    """A request without a key: charge and record, as before keys existed."""
    try:
        payment = service.create_payment(conn, customer_id, cents)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    return 201, payment


def _create_once(conn, key, customer_id, cents):
    """A request with a key. Lookup, charge and save run in one write transaction,
    so a concurrent request with the same key waits here and then sees the result."""
    now = int(time.time())
    if conn.in_transaction:
        conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    try:
        idempotency.purge_expired(conn, now)
        saved = idempotency.find(conn, key)
        if saved is None:
            status, body = _attempt(conn, customer_id, cents)
            idempotency.save(conn, key, customer_id, cents, status, body, now)
        elif saved[:2] != (customer_id, cents):
            status, body = 409, {"error": "idempotency key reused"}
        else:
            status, body = saved[2], saved[3]
        conn.commit()
    except BaseException:
        conn.rollback()
        raise
    return status, body


def _attempt(conn, customer_id, cents):
    """Run the payment inside the caller's transaction and return (status, body).

    A refused attempt is rolled back to a savepoint, not the whole transaction, so the
    write lock is held until the key's result is saved."""
    conn.execute("SAVEPOINT attempt")
    try:
        status, body = 201, service.create_payment(conn, customer_id, cents, commit=False)
    except service.UnknownCustomer:
        status, body = 404, {"error": "no such customer"}
    except gateway.Declined as e:
        status, body = 402, {"error": f"declined: {e}"}
    if status != 201:
        conn.execute("ROLLBACK TO attempt")
    conn.execute("RELEASE attempt")
    return status, body

