"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


class Tree:
    """What dest will hold once the archive is written: the archive's members laid over whatever dest holds now.

    Paths are tuples of names below dest. Every check runs on this, so a link made by an earlier member counts
    when a later member or link is followed through it, and the answer doesn't depend on what is on disk yet."""

    MAX_HOPS = 40

    def __init__(self, root):
        self.root = root
        self.added = {}  # path -> ("dir",) | ("file",) | ("link", linkname)

    def kind(self, path):
        """None, ("dir",), ("file",) or ("link", linkname) for a path that holds no link above its last name."""
        if path == ():
            return ("dir",)
        if path in self.added:
            return self.added[path]
        try:
            mode = os.lstat(os.path.join(self.root, *path)).st_mode
        except (FileNotFoundError, NotADirectoryError):
            return None
        if stat.S_ISLNK(mode):
            return ("link", os.readlink(os.path.join(self.root, *path)))
        return ("dir",) if stat.S_ISDIR(mode) else ("file",)

    def resolve(self, start, relative, follow_last, what):
        """Follow the names in relative from the folder start, through every link met, and return
        (path, through_link, exists): where it ends, whether a link was followed, whether it is there. UnsafeArchive
        if the walk leaves dest at any point, meets an absolute link or loops. A ".." after a name that isn't
        there is refused too, since what that name turns into later would decide where it goes."""
        cur = list(start)
        pending = list(reversed(relative))
        hops = 0
        through = False
        exists = True
        while pending:
            part = pending.pop()
            if part in ("", "."):
                continue
            if part == "..":
                if not exists:
                    raise UnsafeArchive(f"{what} goes up from a name that isn't there")
                if not cur:
                    raise UnsafeArchive(f"{what} leads outside the destination")
                cur.pop()
                continue
            path = tuple(cur) + (part,)
            found = self.kind(path) if exists else None
            if found and found[0] == "link" and (pending or follow_last):
                hops += 1
                if hops > self.MAX_HOPS:
                    raise UnsafeArchive(f"{what} goes through too many links")
                if not found[1] or found[1].startswith("/") or "\x00" in found[1]:
                    raise UnsafeArchive(f"{what} goes through a link to an absolute path")
                pending.extend(reversed(found[1].split("/")))
                through = True
                continue
            cur.append(part)
            if found is None or (found[0] == "file" and pending):
                exists = False
        return tuple(cur), through, exists


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] once every member has passed, or UnsafeArchive.

    The archive is laid out in a Tree in order. A member goes to where its folder really is, links followed, so
    writing it never passes a link on disk; then every link is followed in the finished Tree, and must stay in."""
    tree = Tree(root)
    seen = set()
    plan = []
    links = []  # (real folder of the link, the member)
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.issym():
            if not member.linkname or os.path.isabs(member.linkname) or "\x00" in member.linkname:
                raise UnsafeArchive(f"{name} links to an absolute path")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        *above, last = name.split("/")
        folder, through, exists = tree.resolve((), above, True, name)
        if not exists and through:
            raise UnsafeArchive(f"{name} would be written through a link that leads nowhere")
        for i in range(len(folder)):  # folders the member needs that aren't there yet
            if tree.kind(folder[:i + 1]) is None:
                tree.added[folder[:i + 1]] = ("dir",)
            elif tree.kind(folder[:i + 1])[0] != "dir":
                raise UnsafeArchive(f"{name} would go inside {'/'.join(folder[:i + 1])}, which isn't a folder")
        here = folder + (last,)
        old = tree.kind(here)
        if member.isdir():
            if old is not None and old[0] != "dir":
                raise UnsafeArchive(f"{name} would replace something that's already there")
            tree.added[here] = ("dir",)
        else:
            if old is not None:
                raise UnsafeArchive(f"{name} would replace something that's already there")
            if member.issym():
                tree.added[here] = ("link", member.linkname)
                links.append((folder, name, member))
            else:
                tree.added[here] = ("file",)
        target = os.path.join(root, *here)
        if not paths.is_within(root, os.path.realpath(os.path.dirname(target))):
            raise UnsafeArchive(f"{name} would be written outside the destination")
        plan.append((member, target))
    for folder, name, member in links:
        tree.resolve(folder, member.linkname.split("/"), True, f"{name} -> {member.linkname}")
    return plan


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    with tar.extractfile(member) as src, open(target, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

