    """An idempotency key was sent again with a different customer or amount."""


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, the payment is stored under that key. A later call with
    the same key, customer and cents returns the stored payment and charges nothing.
    The same key with a different customer or cents raises KeyReused. A key of None
    behaves as before.
    """
    if idempotency_key is None:
        _require_customer(conn, customer_id)
        payment = _charge_and_insert(conn, customer_id, cents, None)
        conn.commit()
        return payment

    if conn.in_transaction:
        conn.commit()  # BEGIN IMMEDIATE cannot start inside an open transaction
    # The write lock is taken before the key lookup, so a second request with the
    # same key waits here until the first has committed, then finds its payment.
    conn.execute("BEGIN IMMEDIATE")
    try:
        payment = _keyed(conn, customer_id, cents, idempotency_key)
    except BaseException:
        conn.rollback()  # releases the lock; nothing from this attempt is kept
        raise
    conn.commit()  # releases the lock
    return payment


def _keyed(conn, customer_id, cents, key):
    row = _find_by_key(conn, key)
    if row is None:
        _require_customer(conn, customer_id)
        try:
            return _charge_and_insert(conn, customer_id, cents, key)
        except sqlite3.IntegrityError:
            # Safety net: the lock should prevent this, but if another writer stored
            # the key first, undo this attempt and replay that payment instead.
            conn.rollback()
            row = _find_by_key(conn, key)
            if row is None:
                raise
    return _replay(row, customer_id, cents)


def _require_customer(conn, customer_id):
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)


def _find_by_key(conn, key):
    return conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                        (key,)).fetchone()


def _replay(row, customer_id, cents):
    if (row[1], row[2]) != (customer_id, cents):
        raise KeyReused(row[0])
    return {"id": row[0], "customer_id": row[1], "cents": row[2], "charge_id": row[3]}


def _charge_and_insert(conn, customer_id, cents, key):
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute("INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
                       (customer_id, cents, charge_id, key))
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

